import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[][] ops = new long[(int) q][5];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int ch = (int) h, cw = (int) w;
        long[][] T = new long[ch + 1][cw + 1];
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int a = (int) ops[k][1], b = (int) ops[k][2], c = (int) ops[k][3], d = (int) ops[k][4];
            if (kind == 1) {
                for (int i = a; i <= ch; i += i & -i)
                    for (int j = b; j <= cw; j += j & -j) T[i][j] += ops[k][3];
            } else {
                long total = 0;
                for (int pass = 0; pass < 4; pass++) {
                    int r = (pass & 1) == 0 ? c : a - 1;
                    int cc = (pass & 2) == 0 ? d : b - 1;
                    long sign = (Integer.bitCount(pass) % 2 == 0) ? 1 : -1;
                    long s = 0;
                    for (int i = r; i > 0; i -= i & -i)
                        for (int j = cc; j > 0; j -= j & -j) s += T[i][j];
                    total += sign * s;
                }
                if (out.length() > 0) out.append(" ");
                out.append(total);
            }
        }
        System.out.println(out);
    }
}
